// Pre-sign simulation. Rabby/MetaMask-Blockaid run full tx simulation via
// dedicated backends; we do the honest zero-server version: dry-run the call
// against current chain state with eth_call (catching reverts before gas is
// spent) and read the ownership/approval state that the call would change.
// Result feeds the confirmation sheet as concrete "before → after" facts.
import { parseAbi } from 'viem'
import { client } from '../tx.js'

const ERC721 = parseAbi([
  'function ownerOf(uint256) view returns (address)',
  'function isApprovedForAll(address,address) view returns (bool)',
  'function safeTransferFrom(address,address,uint256)',
])

// { ok, revertReason?, changes: [{what, before, after}] }
export async function simulateTransfer({ chainId, from, to, contract, tokenId, data }) {
  const cl = client(chainId)
  const out = { ok: true, changes: [] }

  // 1. would it revert? (eth_call against latest state, no gas spent)
  let rpcReason = null
  try {
    await cl.call({ account: from, to: contract, data })
  } catch (e) {
    out.ok = false
    rpcReason = (e.shortMessage || e.message || 'reverted').slice(0, 200)
  }

  // 2. observable state the transfer changes. Public RPCs often return a
  // useless "internal error" instead of revert data, so a state-derived
  // explanation is preferred over the RPC's own text when we have one.
  try {
    const owner = await cl.readContract({ address: contract, abi: ERC721, functionName: 'ownerOf', args: [BigInt(tokenId)] })
    out.changes.push({ what: `owner of #${tokenId}`, before: owner, after: to })
    if (owner.toLowerCase() !== String(from).toLowerCase()) {
      out.ok = false
      out.revertReason = `the signing account no longer owns this NFT — the chain says the owner is ${owner}`
    }
  } catch { /* ERC-1155 or non-standard: skip ownership read */ }
  if (!out.revertReason && rpcReason) {
    out.revertReason = /internal error/i.test(rpcReason)
      ? 'the contract rejected this transfer (the RPC did not say why — check ownership and approvals)'
      : rpcReason
  }

  return out
}

// Simulate a revocation: confirm the approval is actually live right now.
export async function simulateRevoke({ chainId, owner, operator, contract, data }) {
  const cl = client(chainId)
  const out = { ok: true, changes: [] }
  try { await cl.call({ account: owner, to: contract, data }) }
  catch (e) { out.ok = false; out.revertReason = (e.shortMessage || e.message).slice(0, 200) }
  try {
    const live = await cl.readContract({ address: contract, abi: ERC721, functionName: 'isApprovedForAll', args: [owner, operator] })
    out.changes.push({ what: 'operator can move your NFTs', before: String(live), after: 'false' })
    if (!live) out.note = 'This approval is already inactive on-chain — revoking would be a no-op.'
  } catch { /* token approval, not collection */ }
  return out
}
