// Address labeling. Rabby/MetaMask ship curated contract-metadata lists so a
// user sees "Uniswap Router" instead of 0x68b3…. We resolve in three tiers,
// cheapest first, and never invent a name:
//   1. your own accounts (from the connected device)
//   2. well-known infrastructure (small curated list, auditable below)
//   3. the indexer's verified contract name (untrusted → shown as text only)
import { CHAINS } from './config.js'

const KNOWN = {
  '0xdef1c0ded9bec7f1a1670819833240f027b25eff': '0x Exchange Proxy',
  '0x1111111254eeb25477b68fb85ed929f73a960582': '1inch Aggregation Router',
  '0x00000000006c3852cbef3e08e8df289169ede581': 'Seaport 1.1 (OpenSea)',
  '0x00000000000000adc04c56bf30ac9d3c0aaf14dc': 'Seaport 1.5 (OpenSea)',
  '0x0000000000000068f116a894984e2db1123eb395': 'Seaport 1.6 (OpenSea)',
  '0x000000000000ad05ccc4f10045630fb830b95127': 'Blur Marketplace',
  '0x68b3465833fb72a70ecdf485e0e4c7bd8665fc45': 'Uniswap Universal Router',
  '0x000000000022d473030f116ddee9f6b43ac78ba3': 'Permit2',
  '0x7f268357a8c2552623316e2562d90e642bb538e5': 'Wyvern Exchange v2 (legacy OpenSea)',
  '0x0000000000000000000000000000000000000000': 'Burn address (zero)',
  '0x000000000000000000000000000000000000dead': 'Burn address (dead)',
}

export function labelFor(address, { accounts = [], contractName = null, chainId } = {}) {
  if (!address) return null
  const a = String(address).toLowerCase()
  const own = accounts.find((x) => String(x.address).toLowerCase() === a)
  if (own) return { text: `your account #${own.index}`, tier: 'own' }
  if (KNOWN[a]) return { text: KNOWN[a], tier: 'known' }
  if (contractName) return { text: String(contractName).slice(0, 40), tier: 'indexer' }
  return null
}

// Resolve an ENS name for display (mainnet registry, any chain's address).
export async function ensFor(address, client) {
  try { return await client.getEnsName({ address }) } catch { return null }
}

export const explorerFor = (chainId) => CHAINS.find((c) => c.id === chainId)?.explorer
